    HazelcastInstanceImpl node2 = null;
    HazelcastInstanceImpl node3 = null;
    SeaTunnelClient engineClient = null;
    SeaTunnelConfig seaTunnelConfig = ConfigProvider.locateAndGetSeaTunnelConfig();
    seaTunnelConfig.getHazelcastConfig().setClusterName(TestUtils.getClusterName(testClusterName));
    try {
        node1 = SeaTunnelServerStarter.createHazelcastInstance(seaTunnelConfig);
        node2 = SeaTunnelServerStarter.createHazelcastInstance(seaTunnelConfig);
        node3 = SeaTunnelServerStarter.createHazelcastInstance(seaTunnelConfig);
        // waiting all node added to cluster
        HazelcastInstanceImpl finalNode = node1;
        Awaitility.await().atMost(10000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals(3, finalNode.getCluster().getMembers().size()));
        Common.setDeployMode(DeployMode.CLIENT);
        ImmutablePair<String, String> testResources = createTestResources(testCaseName, JobMode.STREAMING, testRowNumber, testParallelism, TEST_TEMPLATE_FILE_NAME);
        JobConfig jobConfig = new JobConfig();
        jobConfig.setName(testCaseName);
        ClientConfig clientConfig = ConfigProvider.locateAndGetClientConfig();
        clientConfig.setClusterName(TestUtils.getClusterName(testClusterName));
        engineClient = new SeaTunnelClient(clientConfig);
        JobExecutionEnvironment jobExecutionEnv = engineClient.createExecutionContext(testResources.getRight(), jobConfig);
        ClientJobProxy clientJobProxy = jobExecutionEnv.execute();
        CompletableFuture<JobStatus> objectCompletableFuture = CompletableFuture.supplyAsync(() -> {
            return clientJobProxy.waitForJobComplete();
        });
        Awaitility.await().atMost(60000, TimeUnit.MILLISECONDS).untilAsserted(() -> {
            // Wait some tasks commit finished, and we can get rows from the sink target dir
            Thread.sleep(2000);
            System.out.println(FileUtils.getFileLineNumberFromDir(testResources.getLeft()));
            Assertions.assertTrue(JobStatus.RUNNING.equals(clientJobProxy.getJobStatus()) && FileUtils.getFileLineNumberFromDir(testResources.getLeft()) > 1);
        });
        // shutdown master node
        node1.shutdown();
        Awaitility.await().atMost(600000, TimeUnit.MILLISECONDS).untilAsserted(() -> {
            // Wait job write all rows in file
            Thread.sleep(2000);
            System.out.println(FileUtils.getFileLineNumberFromDir(testResources.getLeft()));
            Assertions.assertTrue(JobStatus.RUNNING.equals(clientJobProxy.getJobStatus()) && testRowNumber * testParallelism * 2 == FileUtils.getFileLineNumberFromDir(testResources.getLeft()));
        });
        // sleep 10s and expect the job don't write more rows.
        Thread.sleep(10000);
        clientJobProxy.cancelJob();
        Awaitility.await().atMost(360000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertTrue(objectCompletableFuture.isDone() && JobStatus.CANCELED.equals(objectCompletableFuture.get())));
        // check the final rows
        Long fileLineNumberFromDir = FileUtils.getFileLineNumberFromDir(testResources.getLeft());
        Assertions.assertEquals(testRowNumber * testParallelism * 2, fileLineNumberFromDir);
    } finally {
        if (engineClient != null) {
            engineClient.shutdown();
        }
        if (node1 != null) {
            node1.shutdown();
        }
        if (node2 != null) {
            node2.shutdown();
        }
        if (node3 != null) {
            node3.shutdown();
        }
    }
}

