@Test
public void testHAByIMapCheckpointIDCounter() throws CheckpointStorageException {
    long jobId = (long) (Math.random() * 1000000L);
    CheckpointStorage checkpointStorage = FactoryUtil.discoverFactory(Thread.currentThread().getContextClassLoader(), CheckpointStorageFactory.class, new CheckpointStorageConfig().getStorage()).create(new HashMap<>());
    CompletedCheckpoint completedCheckpoint = new CompletedCheckpoint(jobId, 1, 1, Instant.now().toEpochMilli(), CheckpointType.COMPLETED_POINT_TYPE, Instant.now().toEpochMilli(), new HashMap<>(), new HashMap<>());
    checkpointStorage.storeCheckPoint(PipelineState.builder().jobId(jobId + "").pipelineId(1).checkpointId(1).states(new ProtoStuffSerializer().serialize(completedCheckpoint)).build());
    IMap<Integer, Long> checkpointIdMap = nodeEngine.getHazelcastInstance().getMap(String.format(IMAP_CHECKPOINT_ID, jobId));
    checkpointIdMap.put(1, 2L);
    Map<Integer, CheckpointPlan> planMap = new HashMap<>();
    planMap.put(1, CheckpointPlan.builder().pipelineId(1).build());
    CheckpointManager checkpointManager = new CheckpointManager(jobId, false, nodeEngine, null, planMap, new CheckpointConfig());
    Assertions.assertTrue(checkpointManager.isCompletedPipeline(1));
    checkpointManager.listenPipeline(1, PipelineStatus.FINISHED);
    Assertions.assertNull(checkpointIdMap.get(1));
    CompletableFuture<Void> future = checkpointManager.shutdown(JobStatus.FINISHED);
    future.join();
    Assertions.assertTrue(checkpointStorage.getAllCheckpoints(jobId + "").isEmpty());
}

@Test
public void testGenerateCheckpointPlan() {
    final IdGenerator idGenerator = new IdGenerator();
    final LogicalDag logicalDag = new LogicalDag();
    fillVirtualVertex(idGenerator, logicalDag, 2);
    fillVirtualVertex(idGenerator, logicalDag, 3);
    JobConfig config = new JobConfig();
    config.setName("test");
    JobImmutableInformation jobInfo = new JobImmutableInformation(1, nodeEngine.getSerializationService().toData(logicalDag), config, Collections.emptyList());
    IMap<Object, Object> runningJobState = nodeEngine.getHazelcastInstance().getMap("testRunningJobState");
    IMap<Object, Long[]> runningJobStateTimestamp = nodeEngine.getHazelcastInstance().getMap("testRunningJobStateTimestamp");
    Map<Integer, CheckpointPlan> checkpointPlans = PlanUtils.fromLogicalDAG(logicalDag, nodeEngine, jobInfo, System.currentTimeMillis(), Executors.newCachedThreadPool(), instance.getFlakeIdGenerator(Constant.SEATUNNEL_ID_GENERATOR_NAME), runningJobState, runningJobStateTimestamp).f1();
    Assertions.assertNotNull(checkpointPlans);
    Assertions.assertEquals(2, checkpointPlans.size());
    // enum(1) + reader(2) + writer(2)
    Assertions.assertEquals(5, checkpointPlans.get(1).getPipelineSubtasks().size());
    // enum
    Assertions.assertEquals(1, checkpointPlans.get(1).getStartingSubtasks().size());
    // enum + reader
    Assertions.assertEquals(2, checkpointPlans.get(1).getPipelineActions().size());
    // enum(1) + reader(3) + writer(3)
    Assertions.assertEquals(7, checkpointPlans.get(2).getPipelineSubtasks().size());
    // enum
    Assertions.assertEquals(1, checkpointPlans.get(2).getStartingSubtasks().size());
    // enum + reader
    Assertions.assertEquals(2, checkpointPlans.get(2).getPipelineActions().size());
}

