@Test
public void testLogicalToPhysical() throws MalformedURLException {
    IdGenerator idGenerator = new IdGenerator();
    Action fake = new SourceAction<>(idGenerator.getNextId(), "fake", new FakeSource(), Sets.newHashSet(new URL("file:///fake.jar")));
    LogicalVertex fakeVertex = new LogicalVertex(fake.getId(), fake, 2);
    Action fake2 = new SourceAction<>(idGenerator.getNextId(), "fake", new FakeSource(), Sets.newHashSet(new URL("file:///fake.jar")));
    LogicalVertex fake2Vertex = new LogicalVertex(fake2.getId(), fake2, 2);
    Action console = new SinkAction<>(idGenerator.getNextId(), "console", new ConsoleSink(), Sets.newHashSet(new URL("file:///console.jar")));
    LogicalVertex consoleVertex = new LogicalVertex(console.getId(), console, 2);
    LogicalEdge edge = new LogicalEdge(fakeVertex, consoleVertex);
    LogicalDag logicalDag = new LogicalDag();
    logicalDag.addLogicalVertex(fakeVertex);
    logicalDag.addLogicalVertex(consoleVertex);
    logicalDag.addEdge(edge);
    JobConfig config = new JobConfig();
    config.setName("test");
    JobImmutableInformation jobImmutableInformation = new JobImmutableInformation(1, nodeEngine.getSerializationService().toData(logicalDag), config, Collections.emptyList());
    IMap<Object, Object> runningJobState = nodeEngine.getHazelcastInstance().getMap("testRunningJobState");
    IMap<Object, Long[]> runningJobStateTimestamp = nodeEngine.getHazelcastInstance().getMap("testRunningJobStateTimestamp");
    PhysicalPlan physicalPlan = PlanUtils.fromLogicalDAG(logicalDag, nodeEngine, jobImmutableInformation, System.currentTimeMillis(), Executors.newCachedThreadPool(), instance.getFlakeIdGenerator(Constant.SEATUNNEL_ID_GENERATOR_NAME), runningJobState, runningJobStateTimestamp).f0();
    Assertions.assertEquals(physicalPlan.getPipelineList().size(), 1);
    Assertions.assertEquals(physicalPlan.getPipelineList().get(0).getCoordinatorVertexList().size(), 1);
    Assertions.assertEquals(physicalPlan.getPipelineList().get(0).getPhysicalVertexList().size(), 2);
}

