@Test
public void testHandleCheckpointTimeout() throws Exception {
    LogicalDag testLogicalDag = TestUtils.createTestLogicalPlan("stream_fakesource_to_file.conf", "test_clear_coordinator_service", JOB_ID);
    JobImmutableInformation jobImmutableInformation = new JobImmutableInformation(JOB_ID, nodeEngine.getSerializationService().toData(testLogicalDag), testLogicalDag.getJobConfig(), Collections.emptyList());
    Data data = nodeEngine.getSerializationService().toData(jobImmutableInformation);
    PassiveCompletableFuture<Void> voidPassiveCompletableFuture = server.getCoordinatorService().submitJob(JOB_ID, data);
    voidPassiveCompletableFuture.join();
    JobMaster jobMaster = server.getCoordinatorService().getJobMaster(JOB_ID);
    // waiting for job status turn to running
    await().atMost(120000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals(JobStatus.RUNNING, jobMaster.getJobStatus()));
    // call checkpoint timeout
    jobMaster.handleCheckpointError(1, new CheckpointException(CheckpointCloseReason.CHECKPOINT_EXPIRED));
    // Because handleCheckpointTimeout is an async method, so we need sleep 5s to waiting job status become running again
    Thread.sleep(5000);
    // test job still run
    await().atMost(120000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals(JobStatus.RUNNING, jobMaster.getJobStatus()));
    PassiveCompletableFuture<JobResult> jobMasterCompleteFuture = jobMaster.getJobMasterCompleteFuture();
    // cancel job
    jobMaster.cancelJob();
    // test job turn to complete
    await().atMost(120000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertTrue(jobMasterCompleteFuture.isDone() && JobStatus.CANCELED.equals(jobMasterCompleteFuture.get().getStatus())));
    testIMapRemovedAfterJobComplete(jobMaster);
}

