        deserializationSchema.deserialize(serializedJson);
        fail("expecting exception message: " + errorMessage);
    } catch (Throwable t) {
        assertEquals(errorMessage, t.getMessage());
    }
    // ignore on parse error
    deserializationSchema = new JsonDeserializationSchema(false, true, schema);
    assertEquals(expected, deserializationSchema.deserialize(serializedJson));
    errorMessage = "ErrorCode:[COMMON-06], ErrorDescription:[Illegal argument] - JSON format doesn't support failOnMissingField and ignoreParseErrors are both enabled.";
    try {
        // failOnMissingField and ignoreParseErrors both enabled
        new JsonDeserializationSchema(true, true, schema);
        Assertions.fail("expecting exception message: " + errorMessage);
    } catch (Throwable t) {
        assertEquals(errorMessage, t.getMessage());
    }
}

@Test
public void testParse() throws IOException {
    TextDeserializationSchema deserializationSchema = TextDeserializationSchema.builder().seaTunnelRowType(seaTunnelRowType).delimiter("#").build();
    TextSerializationSchema serializationSchema = TextSerializationSchema.builder().seaTunnelRowType(seaTunnelRowType).delimiter("#").build();
    SeaTunnelRow seaTunnelRow = deserializationSchema.deserialize(content.getBytes());
    String data = new String(serializationSchema.serialize(seaTunnelRow));
    Assertions.assertEquals(((Map<?, ?>) (seaTunnelRow.getField(1))).get("tyrantlucifer"), 18);
    Assertions.assertEquals(((Map<?, ?>) (seaTunnelRow.getField(1))).get("Kris"), 21);
    Assertions.assertArrayEquals((byte[]) seaTunnelRow.getField(12), "tyrantlucifer".getBytes());
    Assertions.assertEquals(seaTunnelRow.getField(2), "tyrantlucifer");
    Assertions.assertEquals(data, content);
}

